import { mkdir, readFile, writeFile } from "node:fs/promises";

// The published binding keeps its engine in module globals. A parser trap can
// corrupt that engine's allocator, so recovery needs fresh JS closures, memory,
// and linker state. Keep the upstream implementation inside a factory, with
// asynchronous instantiation of modules Lumis has already compiled.
// No fetching, compilation, eval, or worker is needed on the recovery path.
export async function buildTreeSitterBinding() {
  const upstream = new URL("../node_modules/web-tree-sitter/web-tree-sitter.js", import.meta.url);
  let source = await readFile(upstream, "utf8");
  const license = await readFile(new URL("LICENSE", upstream), "utf8");
  const replace = (before, after) => {
    if (source.split(before).length !== 2) {
      throw new Error(`web-tree-sitter binding changed: ${before}`);
    }
    source = source.replace(before, after);
  };
  const replaceBetween = (start, end, replacement) => {
    const from = source.indexOf(start);
    const to = source.indexOf(end, from);
    if (from < 0 || to < 0) throw new Error(`web-tree-sitter binding changed: ${start}`);
    replace(source.slice(from, to), replacement);
  };

  replaceBetween(
    "  static async load(input) {",
    "    const symbolNames",
    "  static async load(input) {\n    const mod = await C.loadWebAssemblyModule(input, { loadAsync: true });\n",
  );
  replaceBetween(
    "  var ENVIRONMENT_IS_NODE =",
    "  Module.currentQueryProgressCallback",
    "  const ENVIRONMENT_IS_NODE = false;\n",
  );
  replaceBetween(
    '  if (ENVIRONMENT_IS_NODE) {\n    var fs = require("fs");',
    "    try {\n      scriptDirectory = new URL",
    "  if (ENVIRONMENT_IS_WEB || ENVIRONMENT_IS_WORKER) {\n",
  );
  replaceBetween(
    '    if (Module["instantiateWasm"]) {',
    "\n  }\n  __name(createWasm",
    "    return receiveInstance(await WebAssembly.instantiate(Module.wasmModule, info2), Module.wasmModule);",
  );
  // Chromium applies its 8 MiB main-thread limit to Instance as well as
  // Module, even for already compiled modules. Keep linker loads async too.
  replace(
    "instance2 = new WebAssembly.Instance(binary, info);",
    "instance2 = await WebAssembly.instantiate(binary, info);",
  );
  replace("export {", "return {");
  replace("//# sourceMappingURL=web-tree-sitter.js.map", "");

  const directory = new URL("../src/generated/", import.meta.url);
  await mkdir(directory, { recursive: true });
  await writeFile(
    new URL("web-tree-sitter.js", directory),
    `/*!\n${license}\n*/\n// Generated by build-tree-sitter-binding.mjs.\nexport function createBinding() {\n${source}\n}\n`,
  );
  await writeFile(
    new URL("web-tree-sitter.d.ts", directory),
    `import type { TreeSitterBinding } from "../core/tree-sitter.js";
export function createBinding(): TreeSitterBinding;
`,
  );
}
